{
  "passageId": "audio-perceptual-coding",
  "slots": [
    {
      "slot": 1,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 4,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": ["C1-2"],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": ["P2-5"],
          "twist": null
        },
        {
          "number": 3,
          "truth": "TRUE",
          "basis": ["P3-8", "P3-9", "R18"],
          "twist": null
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": ["P4-3"],
          "twist": {
            "type": "NEGATION",
            "targetIds": ["P4-3"],
            "change": "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어난다는 내용을, 주파수가 가까운 두 소리 사이에서는 차폐가 일어나기 어렵다는 내용으로 바꾼다."
          }
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": ["P5-1"],
          "twist": null
        }
      ]
    },
    {
      "slot": 2,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 3,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": ["P1-8", "P1-9", "R5"],
          "twist": {
            "type": "CONDITION_SHIFT",
            "targetIds": ["P1-9"],
            "change": "초기 녹음기 이후의 매체에서도 한동안 아날로그 기록이 지속되었다는 내용을, 초기 녹음기 바로 다음에 등장한 매체부터 디지털 기록으로 전환되었다는 내용으로 바꾼다."
          }
        },
        {
          "number": 2,
          "truth": "FALSE",
          "basis": ["P2-2", "P2-3", "P2-4"],
          "twist": {
            "type": "SUBSTITUTION",
            "targetIds": ["P2-4"],
            "change": "일반적인 16비트 오디오 파일에서 소리 크기를 구별하는 요소를 16자리 이진수의 값에서 소리 크기마다 할당되는 이진수의 자릿수로 바꾼다."
          }
        },
        {
          "number": 3,
          "truth": "TRUE",
          "basis": ["P3-2", "P3-3"],
          "twist": null
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": ["P4-6", "P4-7"],
          "twist": {
            "type": "DIRECTION",
            "targetIds": ["P4-7"],
            "change": "고음의 임계대역이 저음의 임계대역보다 훨씬 넓다는 비교를, 고음의 임계대역이 저음의 임계대역보다 훨씬 좁다는 비교로 뒤집는다."
          }
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": ["P2-6", "P2-7", "R10"],
          "twist": {
            "type": "NEGATION",
            "targetIds": ["P2-7"],
            "change": "오디오 파일의 많은 데이터 양 때문에 저장 공간을 절약하기 위한 압축이 필요하다는 내용을, 데이터 양이 많더라도 저장 공간 절약을 위한 압축은 필요하지 않다는 내용으로 바꾼다."
          }
        }
      ]
    },
    {
      "slot": 3,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "CONCEPT",
      "concept": "차폐 문턱값",
      "answer": 2,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": ["P3-4", "P4-8", "R24"],
          "twist": {
            "type": "CONFLATION",
            "targetIds": ["P3-4", "P4-8", "R24"],
            "change": "차폐를 고려한 감지 기준인 차폐 문턱값을 조용할 때의 감지 기준인 최소가청강도와 동일시하여, 차폐 여부를 구별하지 않는 동일한 기준으로 설명한다."
          }
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": ["P5-2"],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": ["P5-3"],
          "twist": {
            "type": "DIRECTION",
            "targetIds": ["P5-3"],
            "change": "차폐 문턱값을 넘는 소리에서 소리 크기와 문턱값의 차이가 클수록 비트를 많이 할당한다는 내용을, 그 차이가 클수록 비트를 적게 할당한다는 내용으로 뒤집는다."
          }
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": ["P5-4", "P5-5", "R34"],
          "twist": {
            "type": "NEGATION",
            "targetIds": ["P5-5"],
            "change": "차폐 문턱값보다 작아 들리지 않는 소리를 제거한다는 내용을, 들리지 않는다는 판단은 유지하되 해당 소리를 제거하지 않고 남겨 둔다는 내용으로 바꾼다."
          }
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": ["P4-8"],
          "twist": {
            "type": "SUBSTITUTION",
            "targetIds": ["P4-8"],
            "change": "차폐 문턱값이 나타내는 물리량을 차폐를 고려하여 감지할 수 있는 소리 크기의 최솟값에서 소리 주파수의 최솟값으로 바꾼다."
          }
        }
      ]
    }
  ]
}

